 static string MoneyText(string value){if(value.IndexOf("CR",StringComparison.OrdinalIgnoreCase)<0)return value;value=Regex.Replace(value,@"\b(\d+)\s+(?:CR|CREDITS?)\b",m=>"$"+m.Groups[1].Value,RegexOptions.IgnoreCase);return Regex.Replace(value,@"\bCREDITS\s+(\d+)\b",m=>"BUDGET $"+m.Groups[1].Value,RegexOptions.IgnoreCase);}
 void DrawBusinessPage(){FrontHeader("STADIUM + MONEY");ClubBusiness b=franchise.Business;Panel(40,178,730,490);TextAt("FOOD",80,208,20,White);TextAt("$"+b.FoodPrice,470,198,34,Gold);MenuPicture("FOOD",80,252,115);TextAt("PARKING",80,389,20,White);TextAt("$"+b.ParkingPrice,470,378,34,Gold);MenuPicture("PARKING",80,433,115);string[] labels={"FOOD - $1","FOOD + $1","PARKING - $2","PARKING + $2","BACK TO OFFICE"};for(int i=0;i<4;i++){float x=245+i%2*245,y=270+i/2*181;DesignButton(labels[i],x,y,225,60,i,selection==i);}DesignButton(labels[4],80,590,640,48,4,selection==4);
  Panel(805,178,425,490);TextAt("FAN HAPPINESS",830,208,16,White);FanFace(845,250,58,b.Fans);TextAt(b.Fans+" / 100",944,261,22,b.Fans<30?Red:Mint);Meter(830,333,366,b.Fans,b.Fans<30?Red:Mint);TextAt("JOB SECURITY",830,374,16,White);Meter(830,412,366,b.Security,b.Security<35?Red:Gold);TextAt(franchise.Fired?"FIRED / OPEN COACHING JOBS":b.Security<35?"BOARD WARNING":"BOARD CONFIDENCE "+b.Security+"%",830,439,11,franchise.Fired||b.Security<35?Red:White);TextAt("HOME ATTENDANCE "+franchise.ExpectedAttendance+"%",830,485,12,Mint);int mood=franchise.PriceMood;TextAt(mood<0?"PRICES: FANS WILL BE UNHAPPY":mood>0?"PRICES: FANS APPRECIATE IT":"PRICES: FAIR TO FANS",830,524,11,mood<0?Red:Mint);TextAt("PROJECTED SALES $"+(int)System.Math.Round(franchise.ExpectedAttendance/100.0*(6+b.FoodPrice*.20+b.ParkingPrice*.18)),830,555,11,Muted);TextAt("LAST GAME",830,588,12,Muted);TextAt("IN $"+b.LastIncome+" / COSTS $"+b.LastExpenses,830,618,12,White);TextAt("BROADCAST $18 / AWAY NET $"+(franchise.ProjectedIncome(franchise.UserTeam,false)-franchise.OperatingCosts(franchise.UserTeam,false))+" / HOME NET $"+(franchise.ProjectedIncome(franchise.UserTeam,true)-franchise.OperatingCosts(franchise.UserTeam,true)),40,692,11,Mint);TextAt(Clip(franchise.Notice,96),40,724,11,Mint);
 }
 void Meter(float x,float y,float width,int percent,Color color){Rect(x,y,width,14,Ink);Rect(x,y,width*Math.Max(0,Math.Min(100,percent))/100f,14,color);}
 void FanFace(float x,float y,float size,int mood){float u=size/16;Rect(x,y,size,size,Gold);Rect(x+3*u,y+4*u,2*u,2*u,Ink);Rect(x+11*u,y+4*u,2*u,2*u,Ink);Rect(x+5*u,y+(mood<30?10:12)*u,6*u,2*u,Ink);if(mood<30){Rect(x+3*u,y+12*u,2*u,2*u,Ink);Rect(x+11*u,y+12*u,2*u,2*u,Ink);}else{Rect(x+3*u,y+10*u,2*u,2*u,Ink);Rect(x+11*u,y+10*u,2*u,2*u,Ink);}}
